# First, let's extract all patient data from Table S1 in supp.pdf/page9
# Then search for Table S2 which should contain organoid response data

s1_data = {}
rows = tables['supp.pdf']['page9']['rows']

# Row 1 is title, Row 2 is header
for i in range(2, len(rows)):
    row = rows[i]
    if len(row) < 8:
        continue
    pid_cell = row[0]
    trg_cell = row[7]

    # Extract patient number
    if isinstance(pid_cell, dict):
        pid_str = str(pid_cell.get('value', ''))
    else:
        pid_str = str(pid_cell)

    if 'Patient-' in pid_str:
        try:
            p_num = int(pid_str.split('-')[1])
        except:
            continue
    else:
        continue

    # Extract TRG
    if isinstance(trg_cell, dict):
        trg_str = str(trg_cell.get('value', '')).strip()
    else:
        trg_str = str(trg_cell).strip()

    s1_data[p_num] = trg_str

print(f"Total patients in Table S1: {len(s1_data)}")
print(f"Patients 81-128 count: {sum(1 for k in s1_data if 81 <= k <= 128)}")

# Show some validation cohort patients
val_patients = {k: v for k, v in s1_data.items() if 81 <= k <= 128}
print(f"\nValidation cohort patients (first 10):")
for k in sorted(val_patients.keys())[:10]:
    print(f"  P{k}: TRG={val_patients[k]}")

# Now search for Table S2 in all sheets
print("\n\nSearching for Table S2...")
for fname in ['supp.pdf', 'mmc2.pdf', 'mmc1.pdf']:
    if fname not in tables:
        continue
    for sname, sheet_obj in tables[fname].items():
        sheet_rows = sheet_obj.get('rows', [])
        if not sheet_rows:
            continue
        # Check first few rows for table title
        for j, row in enumerate(sheet_rows[:3]):
            text = ' '.join([str(c) for c in row if c])
            if 'Table 2' in text or 'Table S2' in text:
                print(f"Found Table S2 in {fname}/{sname}")
                # Print header and first few rows
                for k in range(min(5, len(sheet_rows))):
                    print(f"  Row {k+1}: {sheet_rows[k][:10]}")
                break
